_K1 = {"spur": {3: 2.1, 4: 3.9, 5: 7.5, 6: 14.9, 7: 26.8, 8: 39.1, 9: 52.8, 10: 76.6, 11: 102.6, 12: 146.3},
       "helical": {3: 1.9, 4: 3.5, 5: 6.7, 6: 13.3, 7: 23.9, 8: 34.8, 9: 47.0, 10: 68.2, 11: 91.4, 12: 130.3}}
_K2 = {"spur": 0.0193, "helical": 0.0087}


def dynamic_factor_helical(z1: int, u: float, v: float, wt: float, grade: int, eps_beta: float) -> float:
    "K_v (ISO 6336-1 Method C) for overlap ratio eps_beta. u = z2/z1, v [m/s], wt = K_A·F_t/b [N/mm]."
    gr = int(min(max(grade, 3), 12))
    wt = max(wt, 100.0)
    f = z1 * v / 100 * math.sqrt(u * u / (1 + u * u))
    kv = {k: 1 + (_K1[k][gr] / wt + _K2[k]) * f for k in _K1}
    if eps_beta >= 1:
        return kv["helical"]
    return kv["spur"] - eps_beta * (kv["spur"] - kv["helical"])


def transverse_factor_helical(grade: int, helical: bool, surface_hardened: bool, wt: float,
                              eps_alpha: float, eps_beta: float, beta_b: float, Z_eps: float) -> float:
    "K_Hα = K_Fα (ISO 6336-1 Method B table above), limited to ε_γ / (ε_α Z_ε²)."
    eps_an = eps_alpha / math.cos(beta_b) ** 2
    last = max(eps_an, 1.4) if helical else max(1 / Z_eps ** 2, 1.2)
    if wt < 100 or grade >= 9 + (0 if surface_hardened else 1):
        k = last
    elif helical:
        k = ({6: 1.1, 7: 1.2, 8: 1.4} if surface_hardened else {6: 1.0, 7: 1.1, 8: 1.2, 9: 1.4}).get(grade, 1.0)
    else:
        k = ({6: 1.0, 7: 1.1, 8: 1.2} if surface_hardened else {6: 1.0, 7: 1.0, 8: 1.1, 9: 1.2}).get(grade, 1.0)
    limit = (eps_alpha + eps_beta) / (eps_alpha * Z_eps ** 2)
    return max(1.0, min(k, limit))

