@dataclass(frozen=True)
class HelicalPairRating:
    """
    Result of `rate_helical_pair`.

    T1, T2    : pinion and gear torques [N·m]
    F_t       : tangential force at the reference circle [N] (ISO 6336 nominal load)
    v         : pitch line velocity [m/s]
    factors   : the load and geometry factors used
    gears     : GearRating of pinion and gear
    """
    T1: float
    T2: float
    F_t: float
    v: float
    factors: dict
    gears: tuple[GearRating, ...]
    S_Hmin: float
    S_Fmin: float

    @property
    def S_H(self) -> float: return min(r.S_H for r in self.gears)

    @property
    def S_F(self) -> float: return min(r.S_F for r in self.gears)

    @property
    def ok(self) -> bool: return self.S_H >= self.S_Hmin and self.S_F >= self.S_Fmin

    @property
    def limiting(self) -> str:
        "Which gear and failure mode has the lowest margin over its required safety."
        rows = [(r.S_H / self.S_Hmin, f"pitting of the {r.gear}") for r in self.gears]
        rows += [(r.S_F / self.S_Fmin, f"root breakage of the {r.gear}") for r in self.gears]
        return min(rows)[1]

    def table(self) -> str:
        "Fixed-width text table of the results."
        hdr = (f"{'gear':8s} {'cycles':>9s} {'σH':>7s} {'σHP':>7s} {'S_H':>6s} {'σF':>7s} {'σFP':>7s} {'S_F':>6s} "
               f"{'Y_Fa':>5s} {'Y_Sa':>5s} {'Y_B':>5s} {'Z_NT':>5s} {'Y_NT':>5s}")
        lines = [hdr]
        for r in self.gears:
            lines.append(f"{r.gear:8s} {r.cycles:9.2e} {r.sigma_H:7.0f} {r.sigma_HP:7.0f} {r.S_H:6.2f} "
                         f"{r.sigma_F:7.0f} {r.sigma_FP:7.0f} {r.S_F:6.2f} {r.Y_Fa:5.2f} {r.Y_Sa:5.2f} {r.Y_B:5.2f} "
                         f"{r.Z_NT:5.2f} {r.Y_NT:5.2f}")
        lines.append(f"min S_H = {self.S_H:.2f} (need {self.S_Hmin}), min S_F = {self.S_F:.2f} (need {self.S_Fmin}); "
                     f"limited by {self.limiting}")
        return "\n".join(lines)


def rate_helical_pair(pair: HelicalPair, inp: HelicalRatingInputs,
                      materials: dict[str, GearMaterial] | None = None,
                      rims: dict[str, float | None] | None = None, alternating: bool = False) -> HelicalPairRating:
    """
    ISO 6336 rating of a helical pair (see above).

    materials   : {'pinion', 'gear'} → GearMaterial (default: both case carburized)
    rims        : {'pinion', 'gear'} → rim thickness under the tooth roots [mm] (None or missing: solid)
    alternating : the teeth are loaded on both flanks (reversing drive): Y_M = 0.7
    """
    mats = {"pinion": MATERIALS["case_carburized"], "gear": MATERIALS["case_carburized"]}
    mats.update(materials or {})
    rims = rims or {}
    p, g, mc = pair.pinion, pair.gear, pair.mesh
    u = pair.ratio
    T1 = inp.torque_in
    F_t = 2000 * T1 / p.d
    v = math.pi * p.d * abs(inp.n_in) / 60_000
    b = min(p.b, g.b)
    ea, eb = mc.eps_alpha, mc.eps_beta
    helical = p.beta > 0
    wt = inp.K_A * F_t / b
    Kv = dynamic_factor_helical(p.z, u, v, wt, inp.grade, eb)
    if eb < 1:
        Ze = math.sqrt((4 - ea) / 3 * (1 - eb) + eb / ea)
    else:
        Ze = math.sqrt(1 / ea)
    surf = all(m.kind != "through" for m in mats.values())
    KHa = transverse_factor_helical(inp.grade, helical, surf, wt, ea, eb, p.beta_b, Ze)
    hd = (p.ha + p.hf) * p.mn
    bh = max(b / hd, 3.0)
    NF = bh ** 2 / (1 + bh + bh ** 2)
    KFb = inp.K_Hbeta ** NF
    awt = mc.alpha_wt
    ZH = math.sqrt(2 * math.cos(p.beta_b) * math.cos(awt) / (math.cos(p.alpha_t) ** 2 * math.sin(awt)))
    ZE = _Z_E(mats["pinion"], mats["gear"])
    Zb = 1 / math.sqrt(math.cos(p.beta))
    sH0 = ZH * ZE * Ze * Zb * math.sqrt(F_t / (p.d * b) * (u + 1) / u)
    M1, M2 = _single_pair_factors(p.transverse(), g.transverse(), awt, ea)
    ZB, ZD = (1.0, 1.0) if eb >= 1 else (max(1.0, M1 - eb * (M1 - 1)), max(1.0, M2 - eb * (M2 - 1)))
    KH = inp.K_A * Kv * inp.K_Hbeta * KHa
    KF = inp.K_A * Kv * KFb * KHa
    ean = ea / math.cos(p.beta_b) ** 2
    Ye = 0.25 + 0.75 / ean
    eb1, beta_deg = min(eb, 1.0), min(math.degrees(p.beta), 30.0)
    Yb = max(1 - eb1 * beta_deg / 120, 1 - 0.25 * eb1, 0.75)
    N1 = inp.cycles if inp.cycles is not None else 60 * inp.life_h * abs(inp.n_in)
    cycles = {"pinion": N1, "gear": N1 / u}
    zlvr = {"ground": 0.92, "hobbed": 0.85}[inp.flank_finish]
    YM = 0.7 if alternating else 1.0
    out = []
    for key, gg, Zbd, mate in (("pinion", p, ZB, g), ("gear", g, ZD, p)):
        mat = mats[key]
        sH = Zbd * sH0 * math.sqrt(KH)
        ZNT = life_factor_contact(cycles[key], mat.kind)
        sHlim = mat.sigma_Hlim * ZNT * zlvr
        vg = gg.virtual()
        ff = form_factors(vg)
        YB = rim_factor(vg, rims.get(key))
        b_F = min(gg.b, mate.b + 2 * gg.mn)
        sF = F_t / (b_F * gg.mn) * ff["Y_Fa"] * ff["Y_Sa"] * Ye * Yb * YB * KF
        YNT = life_factor_bending(cycles[key], mat.kind)
        sFlim = mat.sigma_Flim * 2.0 * YNT * YM
        out.append(GearRating(key, "pinion–gear", cycles[key], sH, sHlim / inp.S_Hmin, sHlim / sH,
                              sF, sFlim / inp.S_Fmin, sFlim / sF, ff["Y_Fa"], ff["Y_Sa"], YB, ZNT, YNT))
    factors = {"K_A": inp.K_A, "K_v": Kv, "K_Hbeta": inp.K_Hbeta, "K_Fbeta": KFb, "K_Halpha": KHa,
               "Z_H": ZH, "Z_E": ZE, "Z_eps": Ze, "Z_beta": Zb, "Z_B": ZB, "Z_D": ZD, "Y_eps": Ye, "Y_beta": Yb,
               "Y_M": YM, "Z_LvR": zlvr}
    return HelicalPairRating(T1, T1 * u * inp.efficiency, F_t, v, factors, tuple(out), inp.S_Hmin, inp.S_Fmin)
